    # ── user prompt builders ─────────────────────────────────

    def _build_generate_user_prompt(
        self, topic: str, count_es: dict[str, int], count_ru: dict[str, int],
        level: str, dialect: str, examples: list[str] | None = None,
        forwarded_posts: list[str] | None = None,
    ) -> str:
        """Build user prompt with specific task parameters for quiz generation."""
        total_es = sum(count_es.values())
        total_ru = sum(count_ru.values())
        total = total_es + total_ru

        def _cat_list(counts: dict[str, int], lang: str) -> str:
            lines = []
            for key, n in counts.items():
                if n > 0:
                    lines.append(f"  - {n} de categoría '{key}'")
            return "\n".join(lines) if lines else f"  (ninguno en {lang})"

        es_list = _cat_list(count_es, "español")
        ru_list = _cat_list(count_ru, "ruso")

        # Build examples section (always present as baseline)
        examples_section = ""
        if examples:
            examples_text = "\n".join(f"  - {e}" for e in examples)
            examples_section = (
                f"\nORACIONES DEL POST ORIGINAL — ESTA ES LA BASE PRINCIPAL:\n"
                f"{examples_text}\n\n"
                f"REGLA CRÍTICA: El 60% de los quizzes DEBE venir de estas oraciones.\n"
                f"Estas oraciones son el material original del estudiante.\n"
                f"Modifícalas, extrae vocabulario, crea vacíos, pregunta sobre su significado.\n"
                f"El 40% restante pueden ser preguntas nuevas que complementen el tema.\n"
            )

        # Build multi-post ADDITIONAL context (added on top of baseline when 2+ posts)
        multi_post_addition = ""
        if forwarded_posts and len(forwarded_posts) > 1:
            posts_text = "\n\n---\n\n".join(forwarded_posts)
            multi_post_addition = (
                f"\n\n{'='*60}\n"
                f"QUIZ SEMANAL BASADO EN MÚLTIPLES POSTS\n"
                f"{'='*60}\n\n"
                f"El usuario reenvió {len(forwarded_posts)} posts de canales de español.\n"
                f"Este quiz es parte de una actividad SEMANAL de aprendizaje.\n\n"
                f"POSTS ORIGINALES:\n{posts_text}\n\n"
                f"INSTRUCCIONES PARA QUIZ SEMANAL:\n"
                f"- Crea quizzes que cubran el TEMA GENERAL que unifica todos los posts\n"
                f"- Distribuye los quizzes entre los diferentes aspectos de los posts\n"
                f"- Mantén coherencia temática entre todos los quizzes\n"
                f"- El 60% de los quizzes DEBE venir de las oraciones de ESTOS posts\n"
                f"- El 40% restante pueden ser preguntas complementarias sobre el tema\n"
                f"- El quiz semanal integra múltiples fuentes para cobertura temática completa\n"
            )

        return (
            f"Crea quizzes sobre: {topic}\n\n"
            f"Debes generar EXACTAMENTE {total} quizzes:\n\n"
            f"En ESPAÑOL ({total_es}):\n{es_list}\n\n"
            f"En RUSO ({total_ru}):\n{ru_list}\n\n"
            f"Nivel: {level}\n"
            f"Dialecto: {dialect}\n"
            f"{examples_section}"
            f"{multi_post_addition}"
        )

    def _build_topic_user_prompt(self, text: str, is_multi_post: bool, multi_post_context: str) -> str:
        """Build user prompt for topic determination."""
        return (
            f"{text}"
            f"{multi_post_context}"
        )

    def _build_category_counts_user_prompt(
        self, topic: str, examples: list[str],
        count_es: dict[str, int], count_ru: dict[str, int],
        level: str, dialect: str,
    ) -> str:
        """Build user prompt for category count determination."""
        examples_text = "\n".join(f"  - {e}" for e in examples[:20]) if examples else "(sin ejemplos)"
        return (
            f"Tema: {topic}\n"
            f"Nivel: {level} | Dialecto: {dialect}\n\n"
            f"Oraciones de ejemplo:\n{examples_text}\n\n"
            f"Cantidades actuales:\n"
            f"  Español: {count_es}\n"
            f"  Ruso: {count_ru}\n\n"
            "Sugerencias las cantidades óptimas de quizzes por categoría e idioma."
        )

    def _build_review_user_prompt(self, quizzes_data: list[dict], topic: str, level: str, dialect: str) -> str:
        """Build user prompt for quiz review."""
        return (
            f"Tema: {topic} | Nivel: {level} | Dialecto: {dialect}\n\n"
            f"Quizzes a revisar:\n{json.dumps(quizzes_data, ensure_ascii=False, indent=2)}"
        )

    def _build_edit_user_prompt(
        self, topic: str, history: list[dict], quiz_id: int, feedback: str
    ) -> str:
        """Build user prompt for quiz editing."""
        history_text = json.dumps(history, ensure_ascii=False, indent=2)
        return (
            f"Tema: {topic}\n\n"
            f"Quizzes actuales:\n{history_text}\n\n"
            f"Quiz a editar: #{quiz_id}\n\n"
            f"Feedback del usuario: {feedback}\n\n"
            f"Edita SOLO el quiz #{quiz_id} según el feedback. "
            "Devuelve SOLO el quiz editado en formato JSON."
        )